using CustomCodeFramework.Core.Pagination;using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Api.Authorization;using Dhole.Content.Api.Extensions;using Dhole.Content.Application.Taxonomies.CreateTaxonomy;using Dhole.Content.Application.Taxonomies.DeleteTaxonomy;using Dhole.Content.Application.Taxonomies.GetTaxonomies;using Dhole.Content.Application.Taxonomies.UpdateTaxonomy;using Dhole.Content.Contracts.Taxonomies;namespace Dhole.Content.Api.Endpoints;public static class TaxonomyEndpoints{public static IEndpointRouteBuilder MapTaxonomyEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/taxonomies").WithTags("Content Taxonomies").RequireAuthorization();g.MapGet("/",async(int? pageNumber,int? pageSize,string? siteKey,string? kind,string? search,IQueryDispatcher d,CancellationToken ct)=>EndpointResults.FromPaged(await d.DispatchAsync(new GetTaxonomiesQuery(PageRequest.Create(pageNumber??1,pageSize??50),siteKey,kind,search),ct))).RequireScope(ContentScopeNames.View);g.MapPost("/",async(TaxonomyWriteRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new CreateTaxonomyCommand(r.Kind,r.Name,r.Slug,r.Description,r.ParentId,r.SortOrder,r.SiteKey,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);g.MapPut("/{id:guid}",async(Guid id,TaxonomyWriteRequest r,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new UpdateTaxonomyCommand(id,r.Name,r.Slug,r.Description,r.ParentId,r.SortOrder,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Edit);g.MapDelete("/{id:guid}",async(Guid id,ICommandDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new DeleteTaxonomyCommand(id,h.GetCurrentUserId()),ct),h)).RequireScope(ContentScopeNames.Delete);return app;}}
